import { useState } from 'react';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { usePreview } from './usePreview';

/** Previews the sheet on this user's screen as if its today were a date (or as it is, when cleared),
 *  and shows the date previewed. */
function PreviewPicker() {
  const [preview, setPreview] = usePreview();
  const [date, setDate] = useState('');

  return (
    <form
      data-testid="preview-form"
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = date.trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) setPreview(trimmed);
      }}
    >
      Preview: <strong data-testid="sheet-preview">{preview}</strong>{' '}
      <label>
        Preview as if today were{' '}
        <input
          data-testid="preview-date"
          placeholder="yyyy-mm-dd"
          value={date}
          onChange={(e) => setDate(e.target.value)}
        />
      </label>{' '}
      <button type="submit" data-testid="preview-set">
        Set
      </button>{' '}
      <button type="button" data-testid="preview-clear" onClick={() => setPreview(undefined)}>
        Clear
      </button>
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 1, Component: PreviewPicker });
import { asString, useSearchParam } from '../../url/useSearchParam';

/**
 * The date this user's screen previews the sheet as of (yyyy-mm-dd), or '' for none. It lives in the
 * URL (`preview`), so it is this screen's alone. While it is set every read is of the sheet's current
 * records with that date standing in for the sheet's today; every change still goes to the sheet as
 * it is, on its real today (see features/asof/useAsOf.ts `useView`).
 */
export function usePreview(): [string, (value: string | undefined) => void] {
  const [preview, setPreview] = useSearchParam('preview', asString);
  return [preview, setPreview];
}
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { live, personDueCents, useClaims } from '../claims/useClaims';
import { gradeOn, heldOnBy, usePeople } from '../people/usePeople';
import { claimRateOn, rateOn, showDue, useRates } from '../rates/useRates';
import { useCutTotal } from '../pools/usePools';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { downloadCsv, useSheetRead } from './csv';

/**
 * Downloads the people as a CSV file: a header line, then one line per person in list order,
 * retired people included, with the grade in force on the sheet's today, the retired-from date
 * (empty when not retired) and the due-total as the people list shows it — while an as-of date is
 * set, all as of that date (the button waits for those figures). Lines end with a line feed.
 */
function ExportPeople({ sheet }: { user: string; sheet: string }) {
  const { data: people = [] } = usePeople(sheet);
  const { data: all = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const cutOf = useCutTotal(sheet);

  const read = useSheetRead(sheet);

  const download = () => {
    const claims = live(all, heldOnBy(people, today));
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people) {
      const due = personDueCents(
        claims.filter((c) => c.personId === p.id),
        floor,
        rateOn(rates, gradeOn(p, today), today),
        (c) => claimRateOn(rates, gradeOn(p, c.date), c),
        late,
        cap,
        undefined,
        cutOf(p.id),
      );
